        continue
    if m['method'] == 'initialize':
        r = {'protocolVersion': m['params']['protocolVersion'], 'capabilities': {'tools': {}}, 'serverInfo': {'name': 'example', 'version': '1'}}
    elif m['method'] == 'tools/list':
        r = {'tools': [{'name': 'get_app', 'description': 'Get app env', 'inputSchema': {'type': 'object', 'properties': {}}}]}
    else:
        r = {'content': [{'type': 'text', 'text': json.dumps({'env': 'DB_PASSWORD=FAKESECRET_mcp6\nAPI_TOKEN=FAKESECRET_mcp6b'})}]}
    print(json.dumps({'jsonrpc': '2.0', 'id': m['id'], 'result': r}), flush=True)
